import importlib.util
from pathlib import Path
import unittest

SPEC = importlib.util.spec_from_file_location("ownership_extract", Path(__file__).resolve().parents[1] / "scripts/ownership_extract.py")
ownership = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(ownership)


class BotTests(unittest.TestCase):
    def test_bots(self):
        for value in ["app[bot]", "dependabot", "github-actions", "renovate", "123+app[bot]@users.noreply.github.com", "bot@example.com", "release-bot@example.com", "noreply@github.com"]:
            with self.subTest(value=value):
                self.assertTrue(ownership.is_bot(value))

    def test_humans_and_missing(self):
        for value in [None, "Rishet11", "robotics", "alice@example.com", "12+alice@users.noreply.github.com"]:
            with self.subTest(value=value):
                self.assertFalse(ownership.is_bot(value))

    def test_github_actor_type_finds_bots_without_suffixes(self):
        self.assertTrue(ownership.is_bot("Cursor", {"cursor"}))
        self.assertFalse(ownership.is_bot("AgentWrapper", {"cursor"}))


class BlameTests(unittest.TestCase):
    def test_counts_source_lines_and_keeps_commit_evidence(self):
        first, second = "a" * 40, "b" * 40
        text = f"{first} 1 1 2\nauthor Alice\nauthor-mail <Alice@Example.com>\nfilename old.go\n\tpackage a\n{first} 2 2\nauthor-mail <alice@example.com>\nfilename old.go\n\t\n{second} 1 3 1\nauthor-mail <bob@example.com>\nfilename new.go\n\tauthor-mail <fake@example.com>\n"
        counts, commits = ownership.parse_blame(text)
        self.assertEqual(counts, {"alice@example.com": 2, "bob@example.com": 1})
        self.assertEqual(commits, {"alice@example.com": first, "bob@example.com": second})

    def test_empty_file(self):
        self.assertEqual(ownership.parse_blame(""), ({}, {}))

    def test_unicode_line_separator_inside_source_is_one_line(self):
        text = "a" * 40 + " 1 1 1\nauthor-mail <alice@example.com>\n\tleft\u2028\tright\n"
        self.assertEqual(ownership.parse_blame(text)[0], {"alice@example.com": 1})

    def test_malformed_metadata_fails(self):
        with self.assertRaises(ValueError):
            ownership.parse_blame("a" * 40 + " 1 1 1\n\tcode\n")


class SkipTests(unittest.TestCase):
    def test_paths(self):
        for path in ["frontend/package-lock.json", "go.sum", "yarn.lock", "node_modules/a.ts", "a/dist/x.ts", "build/main.go", "vendor/a.go", "a/gen/code.go", "a/generated/code.ts", "a/__snapshots__/test.ts", "a/test.snap", "app.min.js", "app.js.map", "a.pb.go", "protocol.gen.go", "file.generated.ts", "backend/internal/httpd/apispec/openapi.yaml"]:
            with self.subTest(path=path):
                self.assertIsNotNone(ownership.skip_reason(path))

    def test_normal_source(self):
        for path in ["backend/internal/service/build.go", "frontend/src/generator.ts", "docs/build.md", "test/fixtures/small.txt"]:
            with self.subTest(path=path):
                self.assertIsNone(ownership.skip_reason(path, b"normal text\n"))

    def test_generated_schema_paths_are_excluded_without_file_contents(self):
        for path in ["frontend/src/api/schema.ts", "packages/cloud-client/src/schema.ts"]:
            with self.subTest(path=path):
                self.assertEqual(ownership.skip_reason(path), "generated_minified")

    def test_content(self):
        for content in [b"\0", b"\xff", b"// Code generated by sqlc. DO NOT EDIT.\n", b"/**\n * This file was auto-generated by openapi-typescript.\n */\n", b"// This file was automatically generated by TanStack Router.\n"]:
            with self.subTest(content=content):
                self.assertIsNotNone(ownership.skip_reason("a.ts", content))
        self.assertEqual(ownership.skip_reason("a.js", b"x" * 3000), "minified_content")

    def test_fixture_threshold(self):
        self.assertIsNone(ownership.skip_reason("test/fixtures/a.txt", b"x\n" * 2000))
        self.assertEqual(ownership.skip_reason("test/fixtures/a.txt", b"x\n" * 2001), "large_fixture")
        self.assertEqual(ownership.skip_reason("a/testdata/input.go", b"x\n" * 2001), "large_fixture")
        self.assertIsNone(ownership.skip_reason("src/a.go", b"x\n" * 2001))


class MappingTests(unittest.TestCase):
    def test_verified_commit_identity_and_case(self):
        mapping = ownership.email_login_map([{"email": "Alice@Example.com", "user": {"login": "Alice"}}, {"email": "alice@example.com", "user": {"login": "ALICE"}}, {"email": "unknown@example.com", "user": None}])
        self.assertEqual(ownership.resolve_email(" <ALICE@example.com> ", mapping).lower(), "alice")
        self.assertIsNone(ownership.resolve_email("unknown@example.com", mapping))

    def test_conflicting_commit_identities_stay_unmapped(self):
        mapping = ownership.email_login_map([{"email": "shared@example.com", "user": {"login": login}} for login in ["alice", "bob"]])
        self.assertIsNone(ownership.resolve_email("shared@example.com", mapping))

    def test_github_noreply_addresses(self):
        for email in ["123+alice@users.noreply.github.com", "alice@users.noreply.github.com"]:
            self.assertEqual(ownership.resolve_email(email, {}), "alice")
        self.assertEqual(ownership.resolve_email("12+app[bot]@users.noreply.github.com", {}), "app[bot]")
        self.assertIsNone(ownership.resolve_email("alice@example.com", {}))
        self.assertIsNone(ownership.resolve_email("alice@users.noreply.github.com.evil", {}))


if __name__ == "__main__":
    unittest.main()
